import { useState, useCallback } from 'react';

export interface BoundingBox {
    x: number;
    y: number;
    width: number;
    height: number;
}

export interface MultiSelectState {
    selectedIds: Set<string>;
    isSelecting: boolean;
    selectionBox: BoundingBox | null;
}

export function useMultiSelect() {
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [isSelecting, setIsSelecting] = useState(false);
    const [selectionBox, setSelectionBox] = useState<BoundingBox | null>(null);

    const toggleSelect = useCallback((id: string, isCtrlPressed: boolean) => {
        setSelectedIds(prev => {
            const newSet = new Set(prev);

            if (isCtrlPressed) {
                // Ctrl+Click: Toggle selection
                if (newSet.has(id)) {
                    newSet.delete(id);
                } else {
                    newSet.add(id);
                }
            } else {
                // Regular click: Select only this item
                newSet.clear();
                newSet.add(id);
            }

            return newSet;
        });
    }, []);

    const selectMultiple = useCallback((ids: string[]) => {
        setSelectedIds(new Set(ids));
    }, []);

    const addToSelection = useCallback((id: string) => {
        setSelectedIds(prev => new Set([...prev, id]));
    }, []);

    const removeFromSelection = useCallback((id: string) => {
        setSelectedIds(prev => {
            const newSet = new Set(prev);
            newSet.delete(id);
            return newSet;
        });
    }, []);

    const clearSelection = useCallback(() => {
        setSelectedIds(new Set());
    }, []);

    const selectAll = useCallback((allIds: string[]) => {
        setSelectedIds(new Set(allIds));
    }, []);

    const isSelected = useCallback((id: string) => {
        return selectedIds.has(id);
    }, [selectedIds]);

    const startBoxSelection = useCallback((startX: number, startY: number) => {
        setIsSelecting(true);
        setSelectionBox({ x: startX, y: startY, width: 0, height: 0 });
    }, []);

    const updateBoxSelection = useCallback((currentX: number, currentY: number) => {
        if (!selectionBox) return;

        const width = currentX - selectionBox.x;
        const height = currentY - selectionBox.y;

        setSelectionBox({
            x: width < 0 ? currentX : selectionBox.x,
            y: height < 0 ? currentY : selectionBox.y,
            width: Math.abs(width),
            height: Math.abs(height)
        });
    }, [selectionBox]);

    const endBoxSelection = useCallback((itemsInBox: string[], isCtrlPressed: boolean) => {
        if (isCtrlPressed) {
            // Add to existing selection
            setSelectedIds(prev => new Set([...prev, ...itemsInBox]));
        } else {
            // Replace selection
            setSelectedIds(new Set(itemsInBox));
        }

        setIsSelecting(false);
        setSelectionBox(null);
    }, []);

    return {
        selectedIds: Array.from(selectedIds),
        selectedCount: selectedIds.size,
        isSelecting,
        selectionBox,
        toggleSelect,
        selectMultiple,
        addToSelection,
        removeFromSelection,
        clearSelection,
        selectAll,
        isSelected,
        startBoxSelection,
        updateBoxSelection,
        endBoxSelection
    };
}
